INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (1,N'A2',NULL,N'/audio/vstep/sample1-listening.mp3',NULL,NULL,N'Speaker: Good afternoon listeners. The annual Da Nang International Fireworks Festival will open next month on June 8th along the Han River.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (2,N'B1',N'Community-based tourism has expanded significantly in the northern mountainous provinces of Vietnam. Local homestays in Ha Giang and Yen Bai allow visitors to experience ethnic cultural traditions while generating sustainable income for rural families.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (3,N'B1',NULL,N'/audio/toeic/test1-p1.mp3',NULL,NULL,NULL,N'general',NULL,N'/img/part1-sample.svg',N'Office workers gathered around a whiteboard',NULL,NULL,0);
