INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (5,N'B2',NULL,N'/audio/toeic/test1-p3.mp3',NULL,NULL,N'Woman: Good morning, Mr. Evans. Did the catering team confirm the order for Friday''s banquet?' + CHAR(10) + N'Man: Yes, they did, but they said they need our final head count by tomorrow noon.' + CHAR(10) + N'Woman: I will email the department heads right away to get their RSVPs.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (6,N'B1',NULL,N'/audio/toeic/test1-p4.mp3',NULL,NULL,N'Attention all passengers on flight VN 214 to Tokyo. Due to routine aircraft inspection, boarding will be delayed by approximately twenty minutes. Please remain seated near Gate 12 until boarding begins.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (7,N'B1',N'Dear Valued Customer, We ------- your recent order and your package is being prepared for shipment.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (8,N'B1',N'MEMORANDUM' + CHAR(10) + N'To: All Branch Employees' + CHAR(10) + N'From: Facilities Management' + CHAR(10) + N'Date: October 14' + CHAR(10) + N'Subject: Elevator Maintenance' + CHAR(10) + N'Please note that the main elevators will undergo safety upgrades this Saturday between 8:00 A.M. and 2:00 P.M. The service elevator near the loading dock will remain accessible throughout this period.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
