INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (19,N'B1',N'Attention all shoppers. The annual summer clearance sale will end today at 9:00 PM. Please bring all selected items to the front registers.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
