INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (22,N'C1',N'Some companies offer employees the option of flexible working hours. In your opinion, what are the advantages and disadvantages of flexible working schedules?',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (23,N'B1',NULL,N'/audio/ielts/cambridge18-t1-listening.mp3',NULL,NULL,N'Guide: Welcome to the University Library induction. Daily guided tours depart every half hour from the information desk starting at 9:30 AM.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (24,N'B2',N'Urban reforestation initiatives have demonstrated measurable cooling effects in metropolitan centres. Studies in Singapore and Seoul indicate that rooftop gardens and street canopy trees reduce localized surface temperatures by up to 2.8 degrees Celsius during peak summer months.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (25,N'B1',NULL,N'/audio/ielts/placement-diagnostic.mp3',NULL,NULL,N'Officer: The student housing office is open Monday to Thursday from 9 AM to 4 PM. On Fridays we close at 1 PM for staff training.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (26,N'B1',N'Renewable energy capacity expanded by 50% in 2023 worldwide, with solar photovoltaics accounting for three-quarters of new installations globally.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (27,N'C1',N'Describe a piece of technology you find difficult to use.' + CHAR(10) + N'You should say:' + CHAR(10) + N'- What it is' + CHAR(10) + N'- When you got it' + CHAR(10) + N'- What you use it for' + CHAR(10) + N'And explain why you find it difficult to use.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (28,N'B2',N'The chart below shows the percentage of households with internet access in three European countries between 2010 and 2020.' + CHAR(10) + N'Summarise the information by selecting and reporting the main features, and make comparisons where relevant.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (29,N'C1',N'Some people believe that unpaid community service should be a compulsory part of high school programmes (such as working for a charity, improving the neighborhood, or coaching younger children).' + CHAR(10) + N'To what extent do you agree or disagree? Give reasons for your answer and include any relevant examples from your own knowledge or experience.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (30,N'B1',NULL,N'/audio/vstep/placement-diagnostic.mp3',NULL,NULL,N'Lecturer: Please submit your research proposals by Friday 5 PM through the faculty portal.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (31,N'B1',N'Artificial intelligence is being integrated into medical imaging across hospital networks, providing diagnostic assistance for radiology scans.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (32,N'B2',N'Topic: Should universities make physical education courses compulsory for all undergraduate students?' + CHAR(10) + N'- Health benefits' + CHAR(10) + N'- Academic stress relief' + CHAR(10) + N'- Student freedom of choice',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (33,N'B2',N'You received an email from an international friend asking for recommendations on historical places to visit in Hanoi.' + CHAR(10) + N'Write an email of at least 120 words suggesting two places, explaining why they are interesting, and giving advice on when to visit.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (34,N'C1',N'Some people think that online learning will eventually replace traditional classrooms. To what extent do you agree or disagree?',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (35,N'B1',NULL,N'/audio/toeic/placement-p1.mp3',NULL,NULL,N'(A) They are boarding a commuter train. (B) They are examining a blueprint on the desk. (C) They are hanging a picture on the wall. (D) The projector screen is being rolled up.',N'general',NULL,N'/img/part1-sample.svg',N'Two engineers standing near an office desk looking closely at an architectural blueprint',NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (36,N'B1',NULL,N'/audio/toeic/placement-p1.mp3',NULL,NULL,N'(A) Some chairs are stacked in the corner. (B) A technician is repairing the light fixture. (C) Documents are being distributed to attendees. (D) Monitor screens are arranged in a row on the table.',N'general',NULL,N'/img/part1-sample.svg',N'An empty modern conference room with computer monitors lined up neatly along the table',NULL,NULL,0);
