INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (40,N'B1',NULL,N'/audio/toeic/placement-p2.mp3',NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (41,N'B1',N'Questions 7 through 9 refer to the following conversation.',N'/audio/toeic/test1-p3.mp3',NULL,NULL,N'Man: Hi, Clara. I just received a call from Apex Logistics regarding our shipment of ergonomic office chairs for the new Seattle branch. Unfortunately, two of the delivery trucks are stuck in Denver due to severe weather.' + CHAR(10) + N'Woman: Oh no! Our interior setup team is scheduled to assemble the workstations this Thursday morning. Did they say when the trucks will arrive?' + CHAR(10) + N'Man: They estimate a forty-eight-hour delay, which means the chairs won''t get there until Friday afternoon.' + CHAR(10) + N'Woman: In that case, I''d better contact the setup agency right away to reschedule their technicians for Saturday so we don''t get charged a standby fee.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (42,N'B1',N'Questions 10 through 12 refer to the following announcement.',N'/audio/toeic/test1-p4.mp3',NULL,NULL,N'Attention, attendees of the Global FinTech Summit. Due to an unexpected audio-visual malfunction in Ballroom A, this morning''s keynote address by Dr. Elena Rostova on cybersecurity trends has been relocated to the Sapphire Auditorium on the mezzanine level. Because the Sapphire Auditorium has a slightly smaller seating capacity, overflow seating with a live video feed will be available in Room 204. Also, please remember to scan your digital conference badge at the entrance of the auditorium if you wish to receive Continuing Professional Education credits for attending this session. Thank you for your cooperation.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (43,N'B1',N'Questions 21 through 24 refer to the following memorandum.' + CHAR(10) + N'' + CHAR(10) + N'To: All Regional Sales Representatives' + CHAR(10) + N'From: Marcus Vance, Director of Operations' + CHAR(10) + N'Date: October 12' + CHAR(10) + N'Subject: Transition to CloudSync Expense Portal' + CHAR(10) + N'' + CHAR(10) + N'Effective November 1, our company will retire the legacy spreadsheet system used for travel expense reporting and transition fully to the CloudSync Expense Portal. This upgrade is designed to [21] ------- the reimbursement process so that employees receive their funds within three business days rather than two weeks.' + CHAR(10) + N'' + CHAR(10) + N'To ensure a smooth transition, all sales staff are required to complete a 30-minute interactive tutorial before October 25. [22] -------. Once you have finished the module, your login credentials will be activated automatically.' + CHAR(10) + N'' + CHAR(10) + N'Please note that any paper receipts dated prior to November 1 must still be processed through the old system. [23] -------, expenses incurred on or after that date will only be accepted via the CloudSync mobile app or web dashboard. Should you encounter any technical difficulties during registration, please contact the IT Help Desk [24] ------- extension 4402.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (44,N'B1',N'Questions 25 through 27 refer to the following workshop schedule.' + CHAR(10) + N'' + CHAR(10) + N'====================================================================' + CHAR(10) + N'PACIFIC NORTHWEST SMALL BUSINESS SYMPOSIUM' + CHAR(10) + N'Date: Friday, November 14 | Venue: Grand Harbor Convention Center' + CHAR(10) + N'====================================================================' + CHAR(10) + N'' + CHAR(10) + N'09:00 A.M. – 10:15 A.M. | Session 1: Mastering Supply Chain Resilience' + CHAR(10) + N'Speaker: Marcus Thorne (COO, Cascade Freight Solutions)' + CHAR(10) + N'Room: Olympic Hall' + CHAR(10) + N'Overview: Learn practical strategies for diversifying suppliers and reducing shipping bottlenecks for regional retailers.' + CHAR(10) + N'' + CHAR(10) + N'10:30 A.M. – 11:45 A.M. | Session 2: Digital Marketing on a Shoestring Budget' + CHAR(10) + N'Speaker: Priya Patel (Founder, Spark Media Agency)' + CHAR(10) + N'Room: Rainier Suite' + CHAR(10) + N'Overview: Discover how to maximize customer engagement using targeted social media campaigns without hiring an external agency. *Note: Attendees should bring a fully charged laptop for the hands-on analytics exercise.*' + CHAR(10) + N'' + CHAR(10) + N'01:00 P.M. – 02:15 P.M. | Session 3: Navigating Commercial Tax Reforms' + CHAR(10) + N'Speaker: Evelyn Cho, CPA (Senior Partner, Cho & Associates)' + CHAR(10) + N'Room: Columbia Room' + CHAR(10) + N'Overview: A detailed breakdown of upcoming state tax incentives for businesses with fewer than 50 full-time employees.' + CHAR(10) + N'' + CHAR(10) + N'*Registration includes complimentary morning coffee and a buffet lunch served in the Emerald Atrium from 11:45 A.M. to 1:00 P.M. Seating for Session 2 is limited to 40 participants; advance sign-up via the symposium mobile app is mandatory.*',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (45,N'B1',N'Questions 28 through 30 refer to the following invoice and e-mail.' + CHAR(10) + N'' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N' PASSAGE 1: INVOICE #INV-8841' + CHAR(10) + N' Vendor: Lumina Botanicals Wholesale' + CHAR(10) + N' Client: Serenity Day Spa (Attn: Hannah Abbott)' + CHAR(10) + N' Order Date: March 3 | Delivery Date: March 6' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N' Item Code | Description                        | Qty | Unit Price | Total' + CHAR(10) + N' LB-102    | Organic Lavender Essential Oil 1L  |  5  | $40.00     | $200.00' + CHAR(10) + N' LB-205    | Eucalyptus Massage Lotion 5L       |  4  | $55.00     | $220.00' + CHAR(10) + N' LB-310    | Bamboo Facial Towels (Pack of 50)  |  6  | $30.00     | $180.00' + CHAR(10) + N' LB-408    | Chamomile Soothing Serum 500ml     |  2  | $65.00     | $130.00' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N' Subtotal: $730.00' + CHAR(10) + N' Shipping (Express Courier): $0.00 (Waived for orders over $500)' + CHAR(10) + N' Total Charged: $730.00' + CHAR(10) + N' *Return Policy: Claims for damaged or incorrect items must be submitted within 5 business days of delivery to qualify for a full refund or free replacement.*' + CHAR(10) + N'' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N' PASSAGE 2: E-MAIL' + CHAR(10) + N' To: billing@luminabotanicals.com' + CHAR(10) + N' From: h.abbott@serenitydayspa.com' + CHAR(10) + N' Date: March 7' + CHAR(10) + N' Subject: Issue with Order #INV-8841' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N' Dear Customer Support,' + CHAR(10) + N'' + CHAR(10) + N' Thank you for the prompt delivery of our wholesale order yesterday. Everything arrived intact except for one item. While the invoice correctly lists the Bamboo Facial Towels we ordered, the boxes we actually received contained standard cotton hand towels instead.' + CHAR(10) + N'' + CHAR(10) + N' Because we have a VIP wellness retreat scheduled for next weekend, we urgently need the correct towels sent out via express courier. Alternatively, if that item is currently out of stock, please issue a refund for that portion of the order to our corporate credit card so we can source them locally. We have left the unopened boxes of cotton towels at our reception desk for your driver to pick up.' + CHAR(10) + N'' + CHAR(10) + N' Sincerely,' + CHAR(10) + N' Hannah Abbott' + CHAR(10) + N' Operations Manager, Serenity Day Spa',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (46,N'B2',N'The line chart shows the percentage of households with access to three energy sources in a European country from 2010 to 2020: solar rose from 10% to 50%, wind from 20% to 35%, and coal fell from 60% to 25%.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (47,N'C1',N'Some people believe that universities should focus on practical job skills, while others think academic knowledge is more important. Discuss both views and give your own opinion.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (48,N'B2',N'You have received an email from the coordinator of a local community project. Reply to explain which weekend activity you can join, ask for the meeting details, and suggest one way to prepare.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (49,N'C1',N'Some people think that cities should invest more in public parks than in shopping centres. Do you agree or disagree? Give reasons and examples.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (50,N'B2',NULL,N'/audio/ielts/placement-diagnostic.mp3',NULL,NULL,N'Applicant: I can attend the laboratory induction on Tuesday. Is the 10 o''clock session still available?' + CHAR(10) + N'Coordinator: It is full, but there are two places in the 2:30 session. Please bring your student card.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (51,N'B2',NULL,N'/audio/ielts/placement-diagnostic.mp3',NULL,NULL,N'Tutor: Your draft is well researched. Before Friday, reorganise the second section around the comparison rather than the dates.' + CHAR(10) + N'Student: Should I add another source?' + CHAR(10) + N'Tutor: Not yet. Make the contrast clearer first.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (52,N'B2',NULL,N'/audio/ielts/placement-diagnostic.mp3',NULL,NULL,N'Guide: The north gallery is closed for lighting work this morning. The sculpture collection has moved upstairs, beside the reading room.' + CHAR(10) + N'Visitor: Is the café affected?' + CHAR(10) + N'Guide: No, it opens at the usual time.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (53,N'B2',NULL,N'/audio/ielts/placement-diagnostic.mp3',NULL,NULL,N'Researcher: We expected the survey to finish in May, but the final interviews were delayed.' + CHAR(10) + N'Manager: Does that change the publication date?' + CHAR(10) + N'Researcher: By only one week. The report should be ready in early July, not late June.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (54,N'B2',N'Urban tree cover can reduce surface temperatures during heatwaves. A city study found the greatest cooling in streets where mature trees shaded continuous sections of pavement; isolated trees produced smaller local effects.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (55,N'B2',N'In a survey of 1,200 commuters, 48% travelled by bus in 2018, compared with 30% by rail and 22% by bicycle. By 2024, rail had risen to 41%, cycling to 25%, while bus use had fallen to 34%.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (56,N'B2',N'The archive digitised its fragile maps first, not because they were the most requested items, but because repeated handling was causing irreversible damage. Popularity rankings were therefore set aside in the initial phase.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (57,N'B2',N'A field experiment compared two restoration sites. Site A received more rain but recovered slowly because compacted soil restricted drainage. Site B received less rain; after its soil was loosened, native plants spread quickly.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (58,N'B2',NULL,N'/audio/vstep/placement-diagnostic.mp3',NULL,NULL,N'Lecturer: The field trip leaves from the main gate at 7:15 on Saturday. Please arrive fifteen minutes early because the bus cannot wait.' + CHAR(10) + N'Student: Do we need to bring lunch?' + CHAR(10) + N'Lecturer: Yes, and wear shoes suitable for walking.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (59,N'B2',NULL,N'/audio/vstep/placement-diagnostic.mp3',NULL,NULL,N'Office staff: The language club meeting has moved from Room 204 to Room 118 because the projector in 204 is being repaired.' + CHAR(10) + N'Student: Is the time still 3 p.m.?' + CHAR(10) + N'Office staff: Yes, the schedule is unchanged.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (60,N'B2',NULL,N'/audio/vstep/placement-diagnostic.mp3',NULL,NULL,N'Announcer: The community clean-up will take place on 18 June, not 16 June as printed on the first notice. Volunteers should register at the library desk by 5 p.m. on Friday.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (61,N'B2',NULL,N'/audio/vstep/placement-diagnostic.mp3',NULL,NULL,N'Student: I cannot attend the computer workshop on Wednesday.' + CHAR(10) + N'Advisor: The Friday group still has spaces. You can transfer online before noon tomorrow; there is no extra fee.' + CHAR(10) + N'Student: I will do that tonight.',N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (62,N'B2',N'A town library introduced a book-delivery service for older residents who cannot travel easily. Volunteers collect requested titles twice a week and leave them at each resident''s home. The service is free, but readers must register by phone.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (63,N'B2',N'The college offers evening classes in basic accounting, workplace communication, and computer skills. Learners may enrol in one course at a time. Applications close on 30 September, and classes begin two weeks later.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (64,N'B2',N'Although the sports centre extended its opening hours, attendance did not rise during the first month. Managers later learned that the last bus left before the new closing time. They are discussing a revised shuttle schedule with the transport office.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (65,N'B2',N'An adult-learning programme originally met every Saturday. After many learners reported shift-work conflicts, the organiser added a Wednesday evening class. The Saturday class remains available for those who prefer it.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (66,N'B1',N'Unit 1 foundational stage for incomplete sentences and completion items.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (67,N'B2',N'The corporate merger announced yesterday between Apex Technologies and Horizon Logistics will create the region''s largest supply chain network. Analysts project a 15% reduction in freight overhead over the upcoming fiscal quarters.',NULL,NULL,NULL,NULL,N'general',NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO Stimuli (StimulusId, CefrLevel, Passage, AudioPath, AudioStartMs, AudioEndMs, Transcript, DomainContext, PromptCopy, ImagePath, ImageAlt, PrepSeconds, ResponseSeconds, DisplayOrder) VALUES (68,N'B1',NULL,NULL,NULL,NULL,NULL,N'general',NULL,N'/images/toeic/test1-p1-q1.jpg',N'Conference meeting room',NULL,NULL,0);
