INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (1,1,1,N'On what date will the festival open?',N'June 1st',N'June 8th',N'June 15th',N'July 8th',N'B',N'The speaker explicitly states June 8th.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (2,2,1,N'What is a primary benefit of community-based tourism described in the text?',N'Rapid industrialization of rural areas',N'Sustainable income for local families',N'Construction of new international airports',N'Government subsidies for tour operators',N'B',N'The passage notes it provides sustainable income for local families while sharing cultural traditions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (3,3,1,N'Look at the photograph and choose the statement that best describes what you see in the image.',N'They are leaving the meeting room.',N'A laptop is being repaired on the desk.',N'A woman is writing on a whiteboard.',N'Some chairs are stacked against the wall.',N'C',N'Option C correctly describes the action: the woman is writing notes on the whiteboard.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'Focus on what the person in the centre is holding and doing.');
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (4,4,1,N'Where did you leave the project folders?',N'Yes, I folded them neatly.',N'On the conference room table.',N'No later than five o''clock.',NULL,N'B',N'Option B directly answers where the folders are placed.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'Listen for a location word that answers "Where".');
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (5,5,1,N'What deadline does the catering team have for the banquet?',N'By the end of today',N'By tomorrow noon',N'On Friday morning',N'Next Monday afternoon',N'B',N'The man says they need the final head count by tomorrow noon.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'Pay attention to what the man says about when they need the count.');
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (6,6,1,N'What is the reason for the flight delay?',N'Adverse weather conditions',N'Routine aircraft inspection',N'A gate reassignment',N'Crew scheduling changes',N'B',N'The speaker explicitly announces that the delay is due to routine aircraft inspection.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'Listen for the phrase following "Due to".');
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (7,7,1,N'The regional manager ------- the quarterly figures before the board meeting.',N'review',N'reviewing',N'will review',N'to review',N'C',N'The sentence lacks a main verb. "will review" expresses future scheduled action.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'Look at the time marker and sentence structure.');
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (8,8,1,N'All client inquiries must be resolved ------- forty-eight hours of submission.',N'in',N'during',N'along',N'within',N'D',N'"within" + time duration indicates action must take place before that span elapses.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'Which preposition indicates within a time span?');
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (9,9,1,N'The design studio provides ------- solutions for modern office spaces.',N'innovation',N'innovative',N'innovatively',N'innovate',N'B',N'"innovative" is the adjective modifying "solutions".',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'The blank modifies the plural noun "solutions".');
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (10,10,1,N'Choose the word or phrase that best completes the sentence in the customer letter.',N'have received',N'will receive',N'are receiving',N'to receive',N'A',N'The present perfect "have received" describes an action that occurred recently with present impact.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'The action happened recently with present relevance.');
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (11,11,1,N'What is the primary purpose of the memorandum?',N'To announce staff promotions',N'To notify employees of maintenance work',N'To schedule an annual fire drill',N'To request feedback on office amenities',N'B',N'The memo announces temporary elevator upgrades and directs staff to an alternate service elevator.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,N'Look at the subject line and the main announcement.');
