INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (17,17,1,N'How long has the client been with the firm?',N'At the downtown office.',N'Since 2019.',N'Yes, she renewed last month.',NULL,N'B',N'The question asks for a duration, and only B provides one.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (18,18,1,N'Woman: Did the catering team confirm the order for Friday''s banquet? Man: Yes, but they need our final head count by tomorrow noon. Woman: I will email the department heads right away.' + CHAR(10) + N'' + CHAR(10) + N'What deadline does the catering team have?',N'By the end of today.',N'By tomorrow noon.',N'On Friday morning.',NULL,N'B',N'The man states the head count is needed by tomorrow noon.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
