INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (23,23,1,N'All employees are required to wear their identification badges ------- visiting the research floor.',N'despite',N'although',N'while',N'unless',N'C',N'The badge is worn during the visit, so ''while'' fits.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (24,24,1,N'The marketing team will ------- the campaign results at Thursday''s meeting.',N'presentation',N'present',N'presented',N'presenting',N'B',N'After the modal ''will'', the base form of the verb is required.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (25,25,1,N'Ms. Alvarez has asked that the revised budget ------- to her by the end of the week.',N'be sent',N'sends',N'sending',N'will send',N'A',N'''Ask that'' takes the subjunctive, so the base form ''be sent'' is correct.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (26,26,1,N'The delay was caused not by the supplier ------- by the customs inspection.',N'and',N'or',N'but',N'so',N'C',N'''Not by ... but by ...'' is the parallel construction the sentence needs.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (27,27,1,N'------- the branch had reported record sales, the regional office remained cautious about the next quarter.',N'Because',N'Since',N'Unless',N'Although',N'D',N'The two clauses contrast, which is what ''Although'' signals.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (28,28,1,N'Thank you for contacting Apex Support. We have received your inquiry regarding account renewal. A representative will review your request and ------- within 24 business hours.',N'respond',N'response',N'responded',N'responding',N'A',N'The modal ''will'' requires the base verb.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
