INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (43,43,1,N'What time does the student housing office close on Fridays?',N'12:00 PM',N'1:00 PM',N'4:00 PM',N'5:00 PM',N'B',N'The officer says: "On Fridays we close at 1 PM".',N'12:00 PM is not the Friday closing time; the recording specifies 1:00 PM.',N'Correct: the housing office closes at 1:00 PM on Fridays.',N'4:00 PM applies Monday through Thursday, not Friday.',N'5:00 PM is never given as a closing time.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (44,44,1,N'What energy source accounted for the majority of new capacity?',N'Wind power',N'Solar photovoltaics',N'Hydroelectricity',N'Geothermal energy',N'B',N'The passage states solar photovoltaics accounted for three-quarters of installations.',N'Wind is not the source identified as the majority of new capacity.',N'Correct: solar photovoltaics accounted for three-quarters of new installations.',N'Hydroelectricity is not named in the passage.',N'Geothermal energy is not named in the passage.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (45,45,1,N'Part 1: Do you work or are you a student? What do you enjoy most about your studies or job?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
