INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (47,47,1,N'Write at least 150 words summarizing the main features and comparisons in the chart.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (48,48,1,N'Write an essay of at least 250 words discussing your opinion with supporting arguments.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (49,49,1,N'How should students submit their research proposals?',N'Printed copy to the office',N'Through the faculty portal',N'By email to the teaching assistant',N'During Monday class',N'B',N'The lecturer specifies "through the faculty portal".',N'The lecturer asks students to submit through the faculty portal, not on paper.',N'Correct: students should submit their proposals through the faculty portal.',N'Emailing the teaching assistant is not the stated submission route.',N'The deadline is Friday at 5 PM, not during Monday class.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (50,50,1,N'What role does artificial intelligence play in medical imaging according to the passage?',N'Replacing hospital doctors completely',N'Providing diagnostic assistance',N'Manufacturing hospital equipment',N'Managing billing departments',N'B',N'The passage states AI provides diagnostic assistance for radiology scans.',N'The passage describes support for radiology, not replacing doctors.',N'Correct: AI provides diagnostic assistance for radiology scans.',N'The passage discusses interpreting scans, not manufacturing equipment.',N'Billing is not mentioned as an AI function.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (51,51,1,N'Part 1: Social Interaction: Talk about your favorite leisure activity. Why do you enjoy it?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (52,52,1,N'Part 2: Topic Development: Present your opinion in 3 minutes based on the prompt.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (53,53,1,N'Write an email responding to your friend (at least 120 words).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (54,54,1,N'Write an essay of at least 250 words discussing both sides and giving your opinion with reasons.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (55,55,1,N'Look at the picture marked Number 1 in your test book and select the statement that best describes what you see.',N'(A) They are boarding a commuter train.',N'(B) They are examining a blueprint on the desk.',N'(C) They are hanging a picture on the wall.',N'(D) The projector screen is being rolled up.',N'B',N'Hai nhân vật trong ảnh đang cúi nhìn vào bản thiết kế trải trên bàn làm việc (examining a blueprint on the desk).',N'Bẫy đồng âm (Homophone trap): Từ "boarding" dễ gây nhầm lẫn âm thanh với "board" (bảng/bàn họp) trong phòng.',N'Đáp án đúng: Mô tả chính xác hành động của hai người đang xem xét bản thiết kế trên mặt bàn.',N'Bẫy hành động sai (Wrong action trap): Có bức tranh/biểu đồ trên tường nhưng đã được treo sẵn, không có ai đang treo.',N'Bẫy bị động hiện tại tiếp diễn (being + V-ed): Màn chiếu đang ở trạng thái tĩnh, không có tác động cuộn lên.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (56,56,1,N'Look at the picture marked Number 2 in your test book and select the statement that best describes what you see.',N'(A) Some chairs are stacked in the corner.',N'(B) A technician is repairing the light fixture.',N'(C) Documents are being distributed to attendees.',N'(D) Monitor screens are arranged in a row on the table.',N'D',N'Tranh tả vật trong phòng họp trống: các màn hình máy tính được xếp thành hàng trên bàn (arranged in a row).',N'Bẫy trạng thái sai: Ghế được xếp quanh bàn làm việc chứ không chồng lên nhau (stacked) ở góc phòng.',N'Bẫy suy diễn chủ thể không tồn tại: Trong hình hoàn toàn không có kỹ thuật viên nào.',N'Bẫy "being + V3/ed" cho tranh tĩnh: Không có người tham dự nên không thể có hành động đang phát tài liệu.',N'Đáp án đúng: Diễn tả chính xác trạng thái tĩnh của các màn hình máy tính xếp dọc theo bàn.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (57,57,1,N'When is the quarterly budget proposal due? — Listen and choose the best response (A, B, or C).',N'(A) Yes, the proposal was approved.',N'(B) Check the schedule Ms. Lin e-mailed this morning.',N'(C) About twenty thousand dollars.',NULL,N'B',N'Câu hỏi "When" nhưng được trả lời gián tiếp bằng cách đẩy trách nhiệm kiểm tra sang lịch trình mà giám đốc tài chính đã gửi.',N'Bẫy Yes/No cho câu hỏi Wh- (When) kết hợp bẫy lặp từ "proposal" (Same-word trap).',N'Đáp án đúng: Phản hồi gián tiếp (Indirect response) chuẩn ETS — chỉ dẫn người hỏi nơi tra cứu thời hạn.',N'Bẫy liên tưởng từ vựng (Associative trap): Nghe thấy "budget" nên đưa ra con số tiền tệ, nhưng câu hỏi hỏi về thời gian "When".',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (58,58,1,N'Who is leading the new client orientation session tomorrow? — Listen and choose the best response (A, B, or C).',N'(A) In the main conference room on the third floor.',N'(B) Mr. Takahashi volunteered to take it over.',N'(C) It was a very informative session.',NULL,N'B',N'Câu hỏi "Who" yêu cầu xác định nhân sự hoặc sự thay đổi phân công công việc.',N'Bẫy sai từ để hỏi: Trả lời cho câu hỏi "Where" thay vì "Who".',N'Đáp án đúng: Nêu tên người phụ trách buổi định hướng khách hàng mới.',N'Bẫy sai thì (Wrong tense trap) và lặp từ "session": Sự kiện diễn ra vào ngày mai (tomorrow) nhưng đáp án lại dùng thì quá khứ "was".',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (59,59,1,N'Why don''t we postpone the product launch until the packaging is finalized? — Listen and choose the best response (A, B, or C).',N'(A) Because the factory is located in Osaka.',N'(B) A light lunch at the cafeteria.',N'(C) That makes sense, given the printing delays.',NULL,N'C',N'"Why don''t we..." là câu đề xuất (suggestion), không phải câu hỏi nguyên nhân "Why" thông thường.',N'Bẫy "Because" kinh điển cho câu đề xuất "Why don''t we...": Nội dung không ăn nhập với đề xuất lùi ngày ra mắt.',N'Bẫy phát âm gần giống (Near-homophone trap): Từ "lunch" (bữa trưa) phát âm gần giống với "launch" (ra mắt sản phẩm).',N'Đáp án đúng: Đồng tình với lời đề xuất và bổ sung lý do thực tế về việc chậm trễ in ấn bao bì.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (60,60,1,N'You''ve already updated the inventory database, haven''t you? — Listen and choose the best response (A, B, or C).',N'(A) The server was down all afternoon, so I couldn''t.',N'(B) In the warehouse next to the loading dock.',N'(C) Yes, the software update is free of charge.',NULL,N'A',N'Câu hỏi đuôi (Tag question) kiểm tra trạng thái hoàn thành công việc, thường được trả lời bằng lý do chưa thể thực hiện.',N'Đáp án đúng: Phản hồi gián tiếp giải thích nguyên nhân chưa thể cập nhật cơ sở dữ liệu.',N'Bẫy liên tưởng từ vựng: Nghe thấy "inventory" (hàng tồn kho) nên gán địa điểm nhà kho (warehouse).',N'Bẫy lặp từ "update": Đánh tráo khái niệm giữa cập nhật dữ liệu kho và bản cập nhật phần mềm miễn phí.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (61,61,1,N'What problem does the man mention?',N'Some office furniture was damaged in transit.',N'A delivery of office chairs has been delayed.',N'A branch office failed a safety inspection.',N'An invoice contains an incorrect standby fee.',N'B',N'Người đàn ông thông báo lô hàng ghế văn phòng bị kẹt ở Denver do thời tiết xấu dẫn đến giao hàng trễ.',N'Bẫy suy diễn quá đà: Lô hàng bị kẹt do thời tiết chứ không hề bị hư hỏng.',N'Đáp án đúng: Paraphrase từ "shipment of ergonomic office chairs... stuck in Denver... forty-eight-hour delay".',N'Bẫy thông tin nhiễu không có trong bài nghe.',N'Bẫy ghép từ (Word-matching trap): Có nhắc tới "standby fee" ở cuối bài nhưng đó là khoản phí người phụ nữ muốn tránh, không phải lỗi hóa đơn.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (62,62,1,N'When is the shipment now expected to arrive?',N'On Thursday morning',N'On Thursday afternoon',N'On Friday afternoon',N'On Saturday morning',N'C',N'Ban đầu dự kiến lắp đặt sáng thứ Năm, nhưng bị trễ 48 giờ nên chiều thứ Sáu hàng mới tới.',N'Bẫy mốc thời gian cũ (Original schedule trap): Thứ Năm là lịch lắp đặt ban đầu của đội kỹ thuật.',N'Bẫy trộn lẫn thông tin giữa "Thursday morning" và "Friday afternoon".',N'Đáp án đúng: Người đàn ông nói rõ "the chairs won''t get there until Friday afternoon".',N'Bẫy mốc thời gian của hành động khác: Thứ Bảy là ngày dời lịch cho đội kỹ thuật viên lắp đặt.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (63,63,1,N'What will the woman most likely do next?',N'Order chairs from a local supplier in Seattle',N'Travel to Denver to inspect the merchandise',N'Reschedule an appointment with a service provider',N'Approve an overtime payment for the drivers',N'C',N'Người phụ nữ quyết định liên hệ ngay với bên lắp đặt (setup agency) để đổi lịch sang thứ Bảy.',N'Bẫy suy diễn không có căn cứ: Hai người chỉ chờ hàng tới chứ không hủy đơn để mua nhà cung cấp khác.',N'Bẫy địa danh: Denver chỉ là nơi xe tải bị kẹt lại do thời tiết.',N'Đáp án đúng: Paraphrase từ "contact the setup agency right away to reschedule their technicians".',N'Bẫy suy diễn từ ngữ cảnh vận tải và chi phí.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (64,64,1,N'Why is the keynote address being moved to a different location?',N'More people registered than originally anticipated.',N'There is a technical problem with the room''s equipment.',N'The keynote speaker requested a smaller stage.',N'Renovation work is taking place on the mezzanine level.',N'B',N'Bài phát biểu chính phải chuyển phòng vì sự cố thiết bị nghe nhìn (audio-visual malfunction) tại Ballroom A.',N'Bẫy đảo ngược nguyên nhân: Bài nói có nhắc tới "smaller seating capacity" ở phòng mới, dễ làm thí sinh tưởng nhầm là đổi phòng vì quá đông người.',N'Đáp án đúng: Paraphrase chuẩn xác cụm "unexpected audio-visual malfunction in Ballroom A".',N'Bẫy thông tin sai lệch: Diễn giả Dr. Elena Rostova không hề yêu cầu đổi sân khấu.',N'Bẫy ghép từ: "mezzanine level" là tầng của hội trường mới (Sapphire Auditorium), không phải nơi đang sửa chữa.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (65,65,1,N'What is available in Room 204?',N'Complimentary refreshments',N'Printed copies of the presentation slides',N'A live broadcast of the speech',N'Technical support for digital badges',N'C',N'Phòng 204 được bố trí làm phòng dự phòng (overflow seating) có truyền hình trực tiếp (live video feed).',N'Bẫy kịch bản hội thảo quen thuộc nhưng không được đề cập trong bài.',N'Bẫy suy diễn không có trong transcript.',N'Đáp án đúng: "A live broadcast" tương đương với "a live video feed" trong bài thông báo.',N'Bẫy trộn từ: "digital badge" xuất hiện ở câu sau nhưng dùng để quét tại cửa hội trường.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (66,66,1,N'How can attendees earn professional credits?',N'By completing an online feedback survey',N'By signing a registration sheet at the front desk',N'By scanning their badges at the auditorium entrance',N'By submitting a summary to Dr. Rostova',N'C',N'Người tham dự cần quét thẻ hội nghị điện tử (scan digital conference badge) tại lối vào hội trường.',N'Bẫy thông lệ thực tế nhưng không có trong bài nói.',N'Bẫy phương thức điểm danh truyền thống (signing a sheet) thay vì quét thẻ kỹ thuật số.',N'Đáp án đúng: Trùng khớp trực tiếp với chỉ dẫn "scan your digital conference badge at the entrance of the auditorium".',N'Bẫy ghép tên nhân vật trong bài vào hành động sai.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (67,67,1,N'All reimbursement requests must be submitted to the accounting department ------- the fifteenth of each month.',N'by',N'until',N'during',N'among',N'A',N'Phân biệt giới từ chỉ hạn chót "by" (trước hoặc muộn nhất là thời điểm nào) và "until" (kéo dài liên tục đến thời điểm nào). Động từ "submit" là hành động điểm nên bắt buộc đi với "by".',N'Đáp án đúng: Giới từ "by + mốc thời gian" diễn tả hạn chót (deadline) cho một hành động hoàn tất như "submitted".',N'Bẫy giới từ kinh điển: "until" chỉ hành động kéo dài liên tục, không dùng cho động từ hoàn tất một lần như "submit".',N'Bẫy giới từ: "during" phải đi với một khoảng thời gian danh từ (e.g., during the month), không đi với ngày cụ thể "the fifteenth".',N'Bẫy nghĩa giới từ: "among" mang nghĩa "trong số (từ 3 đối tượng trở lên)", không dùng để chỉ mốc thời gian.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (68,68,1,N'By the time the chief executive officer arrives at the Tokyo headquarters tomorrow, the legal team ------- the merger contract.',N'finalized',N'will have finalized',N'had finalized',N'is finalizing',N'B',N'Cấu trúc "By the time + S + V(hiện tại đơn), S + will have + V3/ed (tương lai hoàn thành)" diễn tả hành động sẽ hoàn tất trước một thời điểm hoặc hành động khác trong tương lai.',N'Bẫy sai thì: Thì quá khứ đơn mâu thuẫn với trạng từ chỉ tương lai "tomorrow" và mệnh đề "arrives".',N'Đáp án đúng: Thì tương lai hoàn thành (will have + V3) đi chuẩn với mệnh đề trạng ngữ "By the time + Hiện tại đơn".',N'Bẫy công thức máy móc: Nhiều thí sinh học vẹt "By the time" đi với "had V3" mà quên nhìn động từ "arrives ... tomorrow".',N'Bẫy thì hiện tại tiếp diễn: Không phản ánh được tính hoàn tất trước một mốc tương lai của cấu trúc "By the time".',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (69,69,1,N'The newly installed inventory tracking software has made warehouse operations ------- more efficient.',N'consider',N'considerable',N'considerably',N'consideration',N'C',N'Trước tính từ so sánh hơn "more efficient" cần một trạng từ (adverb) để nhấn mạnh mức độ.',N'Bẫy từ loại: Động từ nguyên mẫu không thể đứng bổ nghĩa cho cụm tính từ so sánh "more efficient".',N'Bẫy cấu trúc make + O + Adj: Thí sinh nhìn thấy "made warehouse operations" nên vội chọn tính từ mà bỏ sót cụm tính từ chính "more efficient" ở phía sau.',N'Đáp án đúng: Trạng từ "considerably" bổ nghĩa mức độ cho tính từ so sánh hơn "more efficient".',N'Bẫy từ loại: Danh từ không thể đứng giữa tân ngữ "operations" và cụm tính từ "more efficient".',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (70,70,1,N'Although the marketing interns were given guidance, they designed the social media campaign entirely by -------.',N'they',N'them',N'their',N'themselves',N'D',N'Cụm cố định "by + đại từ phản thân (oneself)" mang nghĩa "tự lực / một mình không ai giúp đỡ". Chủ ngữ là "they" nên dùng "themselves".',N'Bẫy sai hình thái đại từ: Đại từ nhân xưng chủ ngữ không thể đứng sau giới từ "by".',N'Bẫy đại từ tân ngữ: Khi chủ ngữ và tân ngữ cùng chỉ một đối tượng ("they") và đi sau giới từ "by" để chỉ sự tự lực, phải dùng đại từ phản thân.',N'Bẫy tính từ sở hữu: "their" không thể đứng độc lập ở cuối câu mà không có danh từ theo sau.',N'Đáp án đúng: Cấu trúc "by themselves" = "on their own" (tự chính họ thực hiện).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (71,71,1,N'------- the rising cost of raw materials, Falcon Manufacturing managed to keep its retail prices stable this year.',N'Although',N'Despite',N'Because of',N'Unless',N'B',N'Phía sau chỗ trống là một cụm danh từ ("the rising cost of raw materials", không có động từ chia thì) và mang nghĩa nhượng bộ tương phản, do đó cần giới từ "Despite".',N'Bẫy liên từ vs giới từ: "Although" cùng nghĩa tương phản nhưng là liên từ phụ thuộc, bắt buộc theo sau bởi một mệnh đề (S + V).',N'Đáp án đúng: Giới từ chỉ sự nhượng bộ "Despite + Cụm danh từ (Noun Phrase)".',N'Bẫy ngữ nghĩa: Đúng ngữ pháp giới từ nhưng sai logic nhân quả.',N'Bẫy liên từ điều kiện: "Unless" phải đi với mệnh đề (S + V) và không hợp nghĩa câu.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (72,72,1,N'Any employee ------- to attend the leadership seminar in Chicago must obtain written approval from a department head.',N'wishes',N'wished',N'wishing',N'to wish',N'C',N'Rút gọn mệnh đề quan hệ: Câu gốc là "Any employee who wishes to attend...". Động từ chính của câu đã là "must obtain", nên chỗ trống cần hiện tại phân từ chủ động "wishing".',N'Bẫy hai động từ chia thì trong một mệnh đề đơn: Câu đã có động từ chính "must obtain".',N'Bẫy phân từ bị động: Động từ "wish" ở đây mang nghĩa chủ động, không thể rút gọn dạng V-ed bị động.',N'Đáp án đúng: Rút gọn mệnh đề quan hệ chủ động (who wishes -> wishing).',N'Bẫy động từ nguyên mẫu có "to": Không dùng "to V" để rút gọn mệnh đề quan hệ thông thường khi không có số thứ tự.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (73,73,1,N'A comprehensive review of the company''s cybersecurity protocols and backup systems ------- conducted every six months.',N'are',N'is',N'have',N'were',N'B',N'Sự hòa hợp Chủ ngữ - Vị ngữ: Chủ ngữ chính là danh từ số ít "A comprehensive review", không phải cụm danh từ số nhiều đứng ngay trước chỗ trống ("protocols and backup systems").',N'Bẫy danh từ gần nhất (Proximity trap): Thí sinh nhìn thấy "protocols and backup systems" số nhiều nên chọn "are".',N'Đáp án đúng: Động từ to-be số ít "is" hòa hợp với chủ ngữ chính "A comprehensive review" và tạo thể bị động "is conducted".',N'Bẫy sai cả số lẫn thể.',N'Bẫy sai số và sai thì (câu có "every six months" chỉ thói quen định kỳ ở hiện tại).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (74,74,1,N'The new biodegradable packaging is ------- durable enough for international shipping and cost-effective to produce.',N'either',N'neither',N'whether',N'both',N'D',N'Cặp liên từ tương quan: Phía sau có liên từ "and" nối hai tính từ, do đó vị trí phía trước bắt buộc là "both".',N'Bẫy cặp liên từ: "either" phải đi với "or", không đi với "and".',N'Bẫy cặp liên từ: "neither" phải đi với "nor", không đi với "and".',N'Bẫy cặp liên từ: "whether" đi với "or".',N'Đáp án đúng: Cặp liên từ tương quan chuẩn "both A and B".',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (75,75,1,N'Select the best word to fill in blank [21].',N'streamline',N'postpone',N'complicate',N'reimburse',N'A',N'Ngữ cảnh phía sau giải thích nhân viên sẽ nhận được tiền hoàn lại trong 3 ngày thay vì 2 tuần, tức là quy trình được đẩy nhanh / tinh gọn ("streamline").',N'Đáp án đúng: "streamline" (hợp lý hóa, tinh gọn) khớp hoàn hảo với việc rút ngắn thời gian từ 2 tuần xuống 3 ngày.',N'Bẫy từ vựng ngược nghĩa: "postpone" (trì hoãn) mâu thuẫn với mục đích nâng cấp hệ thống.',N'Bẫy ngữ nghĩa: Không ai nâng cấp phần mềm với mục đích làm phức tạp hóa ("complicate") quy trình.',N'Bẫy lặp từ trong ngữ cảnh: Phía sau đã có danh từ "reimbursement process".',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (76,76,1,N'Select the best sentence to fill in blank [22].',N'The quarterly sales targets have been adjusted accordingly.',N'A link to the training video has been sent to your corporate e-mail address.',N'Several clients have requested digital copies of their contracts.',N'Travel allowances will be reduced by ten percent next fiscal year.',N'B',N'Câu trước nhắc tới "a 30-minute interactive tutorial", câu sau nhắc tới "Once you have finished the module...". Do đó câu ở vị trí [22] phải kết nối cách truy cập bài hướng dẫn.',N'Bẫy lạc đề dựa trên đối tượng người nhận: Đoạn văn đang nói về phần mềm hoàn ứng chi phí, không phải chỉ tiêu doanh số.',N'Đáp án đúng: Liên kết mạch lạc giữa "complete a 30-minute interactive tutorial" ở câu trước và "finished the module" ở câu sau.',N'Bẫy từ vựng "digital": Không liên quan đến quy trình đào tạo nội bộ.',N'Bẫy liên tưởng từ "travel expense": Đưa thông tin cắt giảm ngân sách không ăn nhập với mạch hướng dẫn kích hoạt tài khoản.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (77,77,1,N'Select the best transition word to fill in blank [23].',N'For instance',N'Similarly',N'However',N'Therefore',N'C',N'Câu trước nói hóa đơn trước ngày 1/11 vẫn xử lý qua hệ thống cũ; câu sau nói chi phí từ ngày 1/11 trở đi chỉ được nhận qua ứng dụng mới. Hai mệnh đề đối lập nhau nên dùng "However".',N'Bẫy trạng từ liên kết: Câu sau không phải là ví dụ minh họa mà là quy định ngược lại.',N'Bẫy quan hệ tương đồng: Đây là sự tương phản, không phải tương đồng.',N'Đáp án đúng: Thể hiện rõ sự đối lập quy trình giữa các hóa đơn trước ngày 1/11 và từ ngày 1/11 trở đi.',N'Bẫy quan hệ nhân quả: Quy định sau không phải là hệ quả suy ra từ quy định trước.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (78,78,1,N'Select the best word to fill in blank [24].',N'at',N'to',N'with',N'for',N'A',N'Trong tiếng Anh thương mại, khi liên hệ qua số máy lẻ nội bộ (extension + số), giới từ chuẩn luôn là "at" (contact someone at extension 4402).',N'Đáp án đúng: Collocation chuẩn "reach/contact someone at extension + [number]".',N'Bẫy dịch từng từ: Động từ "contact" là ngoại động từ không đi với "to".',N'Bẫy giới từ: "contact with" là lỗi sai phổ biến khi "contact" đóng vai trò là động từ.',N'Bẫy giới từ chỉ mục đích.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (79,79,1,N'Who would most likely benefit from attending Session 3?',N'International freight forwarders',N'Freelance graphic designers seeking agency jobs',N'Owners of companies with a small workforce',N'Software developers building mobile applications',N'C',N'Session 3 trình bày về ưu đãi thuế bang dành cho các doanh nghiệp có dưới 50 nhân viên toàn thời gian (fewer than 50 full-time employees).',N'Bẫy thông tin của phần khác: Liên quan tới nội dung chuỗi cung ứng ở Session 1.',N'Bẫy từ khóa "agency" lấy từ Session 2.',N'Đáp án đúng: Paraphrase cụm "businesses with fewer than 50 full-time employees" thành "companies with a small workforce".',N'Bẫy từ khóa "mobile app" xuất hiện ở dòng chú thích cuối bài.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (80,80,1,N'What is indicated about Ms. Patel''s session?',N'It will take place in the Emerald Atrium.',N'It requires participants to register in advance.',N'It is the first session of the morning.',N'It charges an additional fee for laptop rentals.',N'B',N'Ms. Patel phụ trách Session 2. Chú thích trong Session 2 yêu cầu mang laptop, và chú thích cuối bài ghi rõ Session 2 giới hạn 40 chỗ ngồi và bắt buộc đăng ký trước qua ứng dụng.',N'Bẫy địa điểm: Emerald Atrium là nơi phục vụ bữa trưa buffet, còn phiên của Ms. Patel diễn ra tại Rainier Suite.',N'Đáp án đúng: Kết nối thông tin "Ms. Patel" -> "Session 2" -> "advance sign-up via the symposium mobile app is mandatory".',N'Bẫy thứ tự: Phiên đầu tiên lúc 9:00 sáng là của Mr. Marcus Thorne.',N'Bẫy suy diễn sai: Người tham gia được nhắc tự mang theo laptop đã sạc đầy, không có dịch vụ cho thuê thu phí.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (81,81,1,N'What is included with the symposium registration?',N'A private consultation with a tax accountant',N'Free parking at the Grand Harbor Convention Center',N'A complimentary midday meal',N'A one-year subscription to analytics software',N'C',N'Dòng cuối cùng ghi rõ: "Registration includes complimentary morning coffee and a buffet lunch".',N'Bẫy suy diễn từ diễn giả Evelyn Cho, CPA ở Session 3.',N'Bẫy thông tin không được đề cập (Not mentioned trap).',N'Đáp án đúng: Paraphrase chuẩn từ "complimentary ... buffet lunch" thành "complimentary midday meal".',N'Bẫy từ khóa "analytics" lấy từ bài tập thực hành ở Session 2.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (82,82,1,N'Why did Ms. Abbott send the e-mail?',N'To complain about an unexpected shipping charge',N'To report that some glass bottles were broken',N'To notify the vendor that an incorrect product was delivered',N'To increase the quantity of lotion before the shipment goes out',N'C',N'Trong email, bà Abbott báo rằng thay vì nhận được Bamboo Facial Towels như trên hóa đơn, spa lại nhận nhầm sang khăn tay cotton thông thường.',N'Bẫy thông tin ngược: Hóa đơn ghi rõ phí giao hàng là $0.00 (được miễn phí).',N'Bẫy từ khóa "damaged" ở phần chính sách đổi trả, nhưng email ghi rõ "Everything arrived intact".',N'Đáp án đúng: Spa đặt khăn mặt sợi tre nhưng lại bị giao nhầm khăn tay cotton.',N'Bẫy sai trình tự thời gian: Đơn hàng đã được giao vào ngày hôm qua (March 6).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (83,83,1,N'If the requested item is out of stock, how much money should be refunded to Serenity Day Spa?',N'$30.00',N'$130.00',N'$180.00',N'$220.00',N'C',N'Suy luận chéo 2 văn bản: Trong email (Passage 2), mặt hàng bị giao sai cần hoàn tiền nếu hết hàng là "Bamboo Facial Towels". Đối chiếu lên Hóa đơn (Passage 1), mục "LB-310 | Bamboo Facial Towels" có tổng tiền (Total) là $180.00.',N'Bẫy đơn giá (Unit Price trap): $30.00 chỉ là giá của 1 gói khăn, trong khi spa đặt 6 gói (Tổng $180.00).',N'Bẫy nhầm dòng trên bảng hóa đơn: $130.00 là tổng tiền của mục LB-408 (Chamomile Soothing Serum).',N'Đáp án đúng: Suy luận chéo từ "Bamboo Facial Towels" trong email sang cột Total của mã LB-310 trên hóa đơn ($30.00 x 6 = $180.00).',N'Bẫy nhầm dòng trên bảng hóa đơn: $220.00 là tổng tiền của mục LB-205 (Eucalyptus Massage Lotion).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (84,84,1,N'Why is Serenity Day Spa eligible for a free replacement?',N'Because the total order exceeded $500.00',N'Because Ms. Abbott submitted the claim within five business days of delivery',N'Because Serenity Day Spa is a first-time wholesale customer',N'Because the spa paid an extra fee for shipping insurance',N'B',N'Suy luận chéo: Chính sách cuối hóa đơn (Passage 1) quy định khiếu nại gửi trong vòng 5 ngày làm việc kể từ ngày giao hàng (March 6) sẽ được đổi miễn phí. Email (Passage 2) được gửi ngay ngày March 7 (1 ngày sau khi nhận hàng).',N'Bẫy nhầm điều kiện khuyến mãi: Đơn trên $500 là điều kiện để được miễn phí vận chuyển ban đầu, không phải điều kiện đổi trả hàng lỗi.',N'Đáp án đúng: Kết hợp ngày giao hàng (March 6) + chính sách 5 ngày trên Hóa đơn với ngày gửi email khiếu nại (March 7).',N'Bẫy thông tin không có trong cả hai văn bản.',N'Bẫy suy diễn không có thật: Không có khoản phí bảo hiểm vận chuyển nào trên hóa đơn.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (85,85,1,N'Directions: Read the e-mail below. You will have 10 minutes to read the e-mail and write your response. Your response should be between 60 and 100 words.' + CHAR(10) + N'' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N'From: David Kowalski, Procurement Manager, Apex Retail Group' + CHAR(10) + N'To: Customer Fulfillment Team, Vanguard Electronics' + CHAR(10) + N'Subject: Urgent – Delayed Delivery of Order #VE-9042' + CHAR(10) + N'Sent: October 19, 10:15 A.M.' + CHAR(10) + N'' + CHAR(10) + N'Dear Fulfillment Team,' + CHAR(10) + N'' + CHAR(10) + N'We have still not received our shipment of 200 wireless barcode scanners (Order #VE-9042), which was guaranteed to arrive at our Chicago warehouse yesterday. Because our seasonal inventory audit begins this Thursday, this delay is disrupting our operations. Please explain why our shipment has been delayed and let us know what compensation or expedited shipping solution you can offer.' + CHAR(10) + N'' + CHAR(10) + N'Regards,' + CHAR(10) + N'David Kowalski' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N'' + CHAR(10) + N'Directions: Respond to the e-mail as if you are a Customer Fulfillment Representative at Vanguard Electronics. In your e-mail, do the following:' + CHAR(10) + N'1. Apologize professionally and explain the specific reason for the shipping delay.' + CHAR(10) + N'2. Confirm the exact new delivery date before Thursday.' + CHAR(10) + N'3. Offer a clear form of compensation (e.g., partial refund, discount voucher, or waived shipping fee).' + CHAR(10) + N'(Target length: 60–100 words | Time limit: 10 minutes)',NULL,NULL,NULL,NULL,NULL,N'Tiêu chí chấm điểm ETS Writing Part 2: (1) Giải quyết trọn vẹn cả 3 yêu cầu trong đề bài; (2) Văn phong email thương mại lịch sự, trang trọng; (3) Sử dụng chính xác các từ nối và cấu trúc câu phức; (4) Đạt độ dài tiêu chuẩn 60–100 từ.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (86,86,1,N'Directions: Read the question below. You have 20 minutes to plan, write, and revise your essay. Your essay should be between 150 and 220 words.' + CHAR(10) + N'' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N'PROMPT:' + CHAR(10) + N'Do you agree or disagree with the following statement?' + CHAR(10) + N'"Remote work increases employee productivity more than working in a traditional office."' + CHAR(10) + N'Use specific reasons and examples to support your answer.' + CHAR(10) + N'--------------------------------------------------------------------' + CHAR(10) + N'' + CHAR(10) + N'Essay Guidelines:' + CHAR(10) + N'- State your position clearly in the introductory paragraph.' + CHAR(10) + N'- Develop at least two well-structured body paragraphs with concrete business examples.' + CHAR(10) + N'- Include a concise concluding paragraph summarizing your main argument.' + CHAR(10) + N'(Target length: 150–220 words | Time limit: 20 minutes)',NULL,NULL,NULL,NULL,NULL,N'Tiêu chí chấm điểm ETS Writing Part 3: (1) Bố cục 3 phần (Introduction - Body Paragraphs - Conclusion) mạch lạc; (2) Lập luận nhất quán kèm ví dụ thực tiễn nơi công sở; (3) Đa dạng hóa cấu trúc ngữ pháp và từ vựng học thuật/thương mại; (4) Đạt độ dài 150–220 từ.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (87,87,1,N'Summarise the main trends, select the most important features, and make relevant comparisons. Write at least 150 words.',NULL,NULL,NULL,NULL,NULL,N'Assessment focus: a clear overview, accurate comparisons, selective data, and a coherent progression from 2010 to 2020.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (88,88,1,N'Discuss both views and give your own opinion. Support your position with reasons and relevant examples. Write at least 250 words.',NULL,NULL,NULL,NULL,NULL,N'Assessment focus: address both views, state a consistent position, develop supported ideas, and control paragraph cohesion.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (89,89,1,N'Write a polite email reply covering all three points. Use an appropriate greeting, clear paragraphs, and a suitable closing. Write 120–150 words.',NULL,NULL,NULL,NULL,NULL,N'Assessment focus: fulfil every communicative purpose, maintain an appropriate formal register, and organize a clear email.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (90,90,1,N'Write an opinion essay with a clear position, two developed reasons, and relevant examples. Write 250–300 words.',NULL,NULL,NULL,NULL,NULL,N'Assessment focus: build a logical argument, explain examples, use cohesive paragraphs, and maintain accurate language.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (91,91,1,N'Which induction session can the applicant attend?',N'The 10 o''clock session',N'The 2:30 session',N'The Tuesday evening session',N'Any session without a student card',N'B',N'The 10 o''clock session is full; the coordinator offers two places in the 2:30 session.',N'This repeats the applicant''s first choice, but the coordinator says it is full.',N'This is the alternative session with two available places.',N'No evening session is mentioned in the recording.',N'The card is something to bring, not a condition for choosing a session.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (92,92,1,N'What does the tutor advise the student to do first?',N'Add another source',N'Correct every date',N'Reorganise the section around the comparison',N'Submit the draft on Thursday',N'C',N'The tutor explicitly prioritizes reorganising the section to make the comparison clearer.',N'The tutor says not to add a source yet.',N'The advice is about the comparison, not date accuracy.',N'This paraphrases the tutor''s instruction to make the contrast clearer.',N'The tutor gives a Friday deadline and no Thursday submission instruction.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (93,93,1,N'Where can visitors now find the sculpture collection?',N'Upstairs beside the reading room',N'In the closed north gallery',N'Inside the café',N'Outside the building',N'A',N'The guide says the collection has moved upstairs beside the reading room.',N'This is the new location stated by the guide.',N'The gallery is closed and no longer holds the collection.',N'The café is unaffected and is not the collection location.',N'No outdoor relocation is mentioned.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (94,94,1,N'What changed because of the delayed interviews?',N'The survey will be cancelled',N'The interviews ended one month early',N'The report will be ready in May',N'The report is expected one week later',N'D',N'The report is now expected in early July rather than late June, a one-week shift.',N'The researcher says only the timeline changed.',N'The interviews were delayed, not completed early.',N'May was the expected survey completion, not the report date.',N'This captures the stated shift to early July.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (95,95,1,N'Which condition produced the greatest cooling in the study?',N'Mature trees shading continuous pavement',N'Newly planted trees in parks',N'Isolated trees beside buildings',N'Any street with a wide road',N'A',N'The passage contrasts continuous shade from mature trees with the smaller effects of isolated trees.',N'This matches the reported condition with the greatest cooling.',N'Neither newly planted trees nor parks are identified as the strongest condition.',N'The passage says isolated trees produced smaller effects.',N'Road width is not identified as a factor.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (96,96,1,N'Which option correctly matches the 2024 transport mode with its share? (Matching)',N'Bus — 41%',N'Bicycle — 34%',N'Rail — 41%',N'Bus — 25%',N'C',N'Rail is matched with 41%; the other options pair the wrong mode and percentage.',N'41% is the rail figure; bus use fell to 34%.',N'Cycling is reported at 25%, not 34%.',N'This correctly matches the mode to the 2024 percentage.',N'25% is the bicycle share, while bus use was 34%.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (97,97,1,N'Why were the maps digitised first?',N'They had the highest online readership',N'They were inexpensive to replace',N'They contained no historical information',N'To prevent damage from repeated handling',N'D',N'The passage says preservation needs, rather than popularity, determined the order.',N'The passage explicitly distinguishes preservation from popularity.',N'The maps are described as fragile and at risk of irreversible damage.',N'The passage does not say this.',N'This is the stated preservation reason.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (98,98,1,N'What can be inferred about the restoration at Site B?',N'More rainfall alone guarantees rapid recovery',N'Improved soil drainage may support plant recovery',N'Native plants cannot grow in dry conditions',N'Site A had no compacted soil',N'B',N'The comparison suggests soil condition supported recovery even with less rainfall.',N'Site A had more rainfall but recovered slowly.',N'Site B recovered quickly after the compacted soil problem was addressed.',N'Native plants spread at the site receiving less rain.',N'The passage identifies compacted soil at Site A.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (99,99,1,N'When should students arrive at the main gate?',N'7:00 on Saturday',N'7:15 on Sunday',N'7:30 on Saturday',N'8:15 on Saturday',N'A',N'The trip leaves at 7:15 and students must arrive fifteen minutes earlier, at 7:00.',N'Arriving fifteen minutes before the 7:15 departure means 7:00.',N'The trip is on Saturday, not Sunday.',N'This is after departure and contradicts the instruction.',N'The departure is at 7:15, so this is an hour too late.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (100,100,1,N'Why has the language club changed rooms?',N'The club meeting has been cancelled',N'Room 118 has a better projector',N'The meeting time has changed',N'The projector in Room 204 needs repair',N'D',N'The projector in Room 204 is being repaired; the meeting time remains unchanged.',N'The staff confirms that only the room changed.',N'The reason given is repair work in Room 204.',N'The time remains 3 p.m.',N'This is the reason stated by the office staff.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (101,101,1,N'What should volunteers do by Friday?',N'Clean the library on 16 June',N'Register at the library desk',N'Bring the first notice to the event',N'Arrive at the clean-up by 5 p.m.',N'B',N'The announcer asks volunteers to register at the library desk by 5 p.m.',N'The event date was corrected to 18 June; the task is registration.',N'This is the action and location stated in the announcement.',N'No instruction to bring a notice is given.',N'5 p.m. Friday is the registration deadline, not the event time.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (102,102,1,N'How can the student change workshop groups?',N'Pay for a new registration at the office',N'Ask the student group to change its date',N'Transfer online before noon tomorrow',N'Wait until the Friday workshop begins',N'C',N'The advisor says to transfer online before noon tomorrow; the student plans to do it tonight.',N'The advisor says there is no extra fee.',N'The advisor offers a different group, not a date change.',N'This is the required process and deadline.',N'The transfer must be made before noon tomorrow.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (103,103,1,N'Who is the delivery service mainly designed to help?',N'Older residents who cannot travel easily',N'Volunteers who want free books',N'Visitors who have not joined the library',N'People who live outside the town',N'A',N'The first sentence identifies older residents with limited ability to travel.',N'This restates the group named in the passage.',N'Volunteers deliver the books; they are not the intended readers.',N'The passage says users need to register, but does not identify visitors as the target group.',N'The service is described for residents of the town.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (104,104,1,N'Which option correctly matches a course with its start date? (Matching)',N'Computer skills — 30 September',N'Accounting — one week after applications close',N'Workplace communication — two weeks after 30 September',N'All courses — the application deadline',N'C',N'Classes begin two weeks after applications close on 30 September, so the start is in October.',N'30 September is the application deadline, not the class start date.',N'The passage states a two-week interval.',N'This correctly matches the course schedule stated in the notice.',N'The deadline is for applying; classes begin later.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (105,105,1,N'Why did attendance probably fail to increase?',N'The sports centre reduced its opening hours',N'The transport office closed permanently',N'There were no activities at the centre',N'Public transport was unavailable at closing time',N'D',N'The last bus left before the centre closed, making the extended hours difficult to use.',N'The centre extended, rather than reduced, its hours.',N'The passage says a schedule is being discussed, not that the office closed.',N'No information about activities is provided.',N'The last bus left before the new closing time.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
INSERT INTO ItemVersions (ItemVersionId, ItemId, VersionNumber, Stem, OptionA, OptionB, OptionC, OptionD, KeyLabel, Explanation, RationaleA, RationaleB, RationaleC, RationaleD, EvidenceStart, EvidenceEnd, EvidenceUnit, EvidenceQuote, ReferenceText, ReferenceKind, MinWords, MaxWords, PrepSeconds, ResponseSeconds, MaxSelections, AllowNumber, AcceptedAnswersJson, RequiredKeywords, Hint) VALUES (106,106,1,N'What was the main reason for adding a Wednesday class?',N'The Saturday class was too expensive',N'To accommodate learners with shift-work conflicts',N'The organiser wanted to remove the Saturday class',N'The programme changed to online teaching',N'B',N'The additional class responds to learners'' reported work schedules while keeping the original option.',N'No course fee is mentioned.',N'This is the stated reason for adding an evening alternative.',N'The passage says Saturday remains available.',N'Both options are described as classes; online delivery is not mentioned.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,NULL);
